using System.Text.Json;
using System.Text.Json.Nodes;
using DG.Core.Bridge;
using Xunit;

namespace DG.Tests;

/// <summary>
/// Phase 1303-15 (DGOPN-02): the place_property_script payload generated by data-service
/// (property_scripts.py; fixture regenerated from it) parses and validates in DG.Core, and
/// malformed plans are refused before the canvas is touched.
/// </summary>
public class PropertyScriptPlacementTests
{
    private static readonly string FixturePath = Path.Combine(AppContext.BaseDirectory, "Fixtures", "property-script-plan.json");

    private static JsonNode Fixture() => JsonNode.Parse(File.ReadAllText(FixturePath))!;

    private static PropertyScriptPlan Parse(JsonNode node) =>
        PropertyScriptPlacement.Parse(JsonDocument.Parse(node.ToJsonString()).RootElement);

    [Fact]
    public void Generated_plan_parses_and_validates()
    {
        var plan = Parse(Fixture());

        Assert.Equal("str-openings-01", plan.Project);
        Assert.Equal(new[] { "calculator", "highlighter" }, plan.Scripts.Keys.OrderBy(k => k));
        Assert.Equal(4, plan.Components.Count(c => c.Type == "PROPERTY STATE"));
        var connector = plan.Components.Single(c => c.Key == "connector");
        Assert.True(connector.Reuse && connector.Required);
        Assert.Contains(plan.Wires, w => w.From.ToString() == "validator.ValidStatus" && w.To.ToString() == "highlighter.ValidStatus");
        Assert.Contains(plan.Scripts["highlighter"].Inputs, i => i.Name == "ValidStatus" && i.Access == "tree");
        Assert.StartsWith("#! python3", plan.Scripts["calculator"].Source);
    }

    [Fact]
    public void Every_dg_type_in_the_plan_has_a_known_component_guid()
    {
        var plan = Parse(Fixture());
        foreach (var c in plan.Components.Where(c => c.Kind == "dg"))
        {
            Assert.True(PropertyScriptPlacement.DgComponentTypes.ContainsKey(c.Type), c.Type);
        }
    }

    [Fact]
    public void Wire_to_an_unknown_script_port_is_refused()
    {
        var node = Fixture();
        node["placement"]!["wires"]!.AsArray().Add(new JsonArray("calculator.P9", "prop1.PropValue"));
        var ex = Assert.Throws<PropertyScriptPlanException>(() => Parse(node));
        Assert.Contains("no port 'P9'", ex.Message);
    }

    [Fact]
    public void Unknown_dg_type_is_refused()
    {
        var node = Fixture();
        node["placement"]!["components"]!.AsArray().Add(new JsonObject { ["key"] = "x", ["kind"] = "dg", ["type"] = "BAKE ALL" });
        Assert.Throws<PropertyScriptPlanException>(() => Parse(node));
    }

    [Fact]
    public void Non_python3_script_is_refused()
    {
        var node = Fixture();
        node["calculator"]!["language"] = "csharp";
        Assert.Throws<PropertyScriptPlanException>(() => Parse(node));
    }

    [Fact]
    public void Script_port_that_is_not_an_identifier_is_refused()
    {
        var node = Fixture();
        node["calculator"]!["outputs"]!.AsArray().Add("P1; import os");
        Assert.Throws<PropertyScriptPlanException>(() => Parse(node));
    }

    [Fact]
    public void Toggle_cannot_be_a_wire_target_and_needs_no_port()
    {
        var node = Fixture();
        node["placement"]!["wires"]!.AsArray().Add(new JsonArray("calculator.Report", "run."));
        Assert.Throws<PropertyScriptPlanException>(() => Parse(node));
    }

    [Fact]
    public void Place_command_is_registered()
    {
        Assert.Equal("place_property_script", CanvasBridgeCommands.PlacePropertyScript);
        Assert.Contains(CanvasBridgeCommands.PlacePropertyScript, CanvasBridgeCommands.All);
        Assert.DoesNotContain(CanvasBridgeCommands.PlacePropertyScript, CanvasBridgeCommands.ReadCommands);
    }
}
